methods:
@Builder
  private actionTarget(label: string, icon: Resource, action: () => void) {
    Stack({ alignContent: Alignment.Center }) {
      Row({ space: 5 }) {
        Image(icon).width(18).height(18);
        Text(label)
          .fontFamily(TYPE_APP_SMALL_ACTION.fontFamily)
          .fontWeight(TYPE_APP_SMALL_ACTION.fontWeight)
          .fontSize(TYPE_APP_SMALL_ACTION.fontSizeFp)
          .fontColor(readerAppColor('app.RssSourceFeedPage.actionTarget.fontColor.FF3F372F', this.appThemeScheme))
          .maxLines(1);
      }
      .height(32)
      .padding({ left: 9, right: 9 })
      .alignItems(VerticalAlign.Center)
      .backgroundColor(readerAppColor('app.RssSourceFeedPage.ACTION_BG', this.appThemeScheme))
      .borderRadius(999);
    }
    .height(44)
    .onClick((): void => action());
  }

@Builder
  private entrySectionHeader() {
    Row() {
      Text('全部条目')
        .layoutWeight(1)
        .fontFamily(TYPE_RSS_SECTION_HEADING.fontFamily)
        .fontWeight(TYPE_RSS_SECTION_HEADING.fontWeight)
        .fontSize(TYPE_RSS_SECTION_HEADING.fontSizeFp)
        .fontColor(readerAppColor('TOK_INK', this.appThemeScheme))
        .maxLines(1);
      Row({ space: 5 }) {
        Image((this.appThemeScheme === 'night' ? $r('app.media.rss_manage_theme_night') : $r('app.media.rss_manage'))).width(16).height(16);
        Text('源操作')
          .fontFamily(TYPE_RSS_LINK_ACTION.fontFamily)
          .fontWeight(TYPE_RSS_LINK_ACTION.fontWeight)
          .fontSize(TYPE_RSS_LINK_ACTION.fontSizeFp)
          .fontColor(readerAppColor('TOK_PRIMARY_TEXT', this.appThemeScheme))
          .maxLines(1);
      }
      .height(30)
      .padding({ left: TOK_SPACE_XS, right: TOK_SPACE_XS })
      .alignItems(VerticalAlign.Center)
      .backgroundColor(readerAppColor('TOK_PRIMARY_SOFT', this.appThemeScheme))
      .borderRadius(999)
      .responseRegion({ x: 0, y: -7, width: '100%', height: 44 })
      .onClick((): void => this.onSourceOperations());
    }
    .width('100%')
    .height(34)
    .padding({ left: 2, right: 2 })
    .alignItems(VerticalAlign.Center);
  }

@Builder
  private actionTarget(label: string, icon: Resource, action: () => void) {
    Stack({ alignContent: Alignment.Center }) {
      Row({ space: 5 }) {
        Image(icon).width(18).height(18);
        Text(label)
          .fontFamily(TYPE_APP_SMALL_ACTION.fontFamily)
          .fontWeight(TYPE_APP_SMALL_ACTION.fontWeight)
          .fontSize(TYPE_APP_SMALL_ACTION.fontSizeFp)
          .fontColor(readerAppColor('app.RssEntryDetailPage.actionTarget.fontColor.FF3F372F', this.appThemeScheme))
          .maxLines(1);
      }
      .width('100%')
      .height(34)
      .justifyContent(FlexAlign.Center)
      .alignItems(VerticalAlign.Center)
      .backgroundColor(readerAppColor('app.RssEntryDetailPage.ACTION_BG', this.appThemeScheme))
      .borderRadius(999);
    }
    .layoutWeight(1)
    .height(44)
    .onClick((): void => action());
  }

@Builder
  private actionTarget(
    label: string,
    icon: Resource,
    danger: boolean,
    divider: boolean,
    action: () => void,
  ) {
    Row({ space: 5 }) {
      Image(icon)
        .width(16)
        .height(16);
      Text(label)
        .fontFamily(TYPE_FORM_COMPACT_ACTION.fontFamily)
        .fontWeight(TYPE_FORM_COMPACT_ACTION.fontWeight)
        .fontSize(TYPE_FORM_COMPACT_ACTION.fontSizeFp)
        .fontColor(danger ? readerAppColor('TOK_DANGER', this.appThemeScheme) : readerAppColor('TOK_INK', this.appThemeScheme))
        .maxLines(1);
    }
    .layoutWeight(1)
    .height(44)
    .justifyContent(FlexAlign.Center)
    .alignItems(VerticalAlign.Center)
    .border({ width: { left: divider ? TOK_BORDER_W : 0 }, color: readerAppColor('TOK_ROW_DIVIDER', this.appThemeScheme) })
    .onClick((): void => action());
  }

@Builder
  private managePill() {
    Row({ space: 5 }) {
      Image((this.appThemeScheme === 'night' ? $r('app.media.rss_manage_theme_night') : $r('app.media.rss_manage')))
        .width(16)
        .height(16);
      Text('管理')
        .fontFamily(TYPE_APP_COMPACT_PRIMARY_ACTION.fontFamily)
        .fontWeight(TYPE_APP_COMPACT_PRIMARY_ACTION.fontWeight)
        .fontSize(TYPE_APP_COMPACT_PRIMARY_ACTION.fontSizeFp)
        .fontColor(readerAppColor('TOK_PRIMARY_TEXT', this.appThemeScheme))
        .maxLines(1);
    }
    .width(64)
    .height(34)
    .justifyContent(FlexAlign.Center)
    .alignItems(VerticalAlign.Center)
    .backgroundColor(readerAppColor('app.RssPage.PILL_BG', this.appThemeScheme))
    .border({ width: TOK_BORDER_W, color: readerAppColor('app.RssPage.PILL_BORDER', this.appThemeScheme) })
    .borderRadius(12)
    .responseRegion({ x: 0, y: -5, width: '100%', height: 44 })
    .onClick((): void => this.onManage());
  }

@Builder
  private recentUnreadHeader() {
    Row() {
      Text('最近未读')
        .layoutWeight(1)
        .fontFamily(TYPE_RSS_SECTION_HEADING.fontFamily)
        .fontWeight(TYPE_RSS_SECTION_HEADING.fontWeight)
        .fontSize(TYPE_RSS_SECTION_HEADING.fontSizeFp)
        .fontColor(readerAppColor('TOK_INK', this.appThemeScheme))
        .maxLines(1);
      Row({ space: 5 }) {
        Image((this.appThemeScheme === 'night' ? $r('app.media.rss_view_all_theme_night') : $r('app.media.rss_view_all')))
          .width(20)
          .height(20);
        Text('查看全部')
          .fontFamily(TYPE_RSS_LINK_ACTION.fontFamily)
          .fontWeight(TYPE_RSS_LINK_ACTION.fontWeight)
          .fontSize(TYPE_RSS_LINK_ACTION.fontSizeFp)
          .fontColor(readerAppColor('TOK_PRIMARY_TEXT', this.appThemeScheme))
          .maxLines(1);
      }
      .height(28)
      .padding({ left: TOK_SPACE_XS, right: TOK_SPACE_XS })
      .alignItems(VerticalAlign.Center)
      .backgroundColor(readerAppColor('app.RssPage.VIEW_ALL_BG', this.appThemeScheme))
      .borderRadius(999)
      .responseRegion({ x: 0, y: -8, width: '100%', height: 44 })
      .onClick((): void => this.onModeRequested('all'));
    }
    .width('100%')
    .height(30)
    .padding({ left: 2, right: 2 })
    .alignItems(VerticalAlign.Center);
  }

@Builder
  private filterPill(opt: string) {
    Stack({ alignContent: Alignment.Center }) {
      Text(opt)
        .fontFamily(TYPE_APP_COMPACT_PRIMARY_ACTION.fontFamily)
        .fontWeight(TYPE_APP_COMPACT_PRIMARY_ACTION.fontWeight)
        .fontSize(TYPE_APP_COMPACT_PRIMARY_ACTION.fontSizeFp)
        .fontColor(this.filterValue === opt ? readerAppColor('TOK_ON_PRIMARY', this.appThemeScheme) : readerAppColor('app.RssPage.filterPill.fontColor.FF564D44', this.appThemeScheme))
        .textAlign(TextAlign.Center)
        .maxLines(1);
    }
    .height(30)
    .padding({ left: TOK_SPACE_CONTROL_INLINE, right: TOK_SPACE_CONTROL_INLINE })
    .backgroundColor(this.filterValue === opt ? readerAppColor('app.action.fill', this.appThemeScheme) : readerAppColor('app.RssPage.SOFT_PILL_BG', this.appThemeScheme))
    .borderRadius(999)
    .margin({ right: 6, bottom: 6 })
    .onClick((): void => {
      this.filterValue = opt;
    });
  }

@Builder
  private configActions() {
    Row({ space: TOK_SPACE_XS }) {
      Stack({ alignContent: Alignment.Center }) {
        Text('测试网络连通性')
          .fontFamily(TYPE_APP_COMPACT_PRIMARY_ACTION.fontFamily)
          .fontWeight(TYPE_APP_COMPACT_PRIMARY_ACTION.fontWeight)
          .fontSize(TYPE_APP_COMPACT_PRIMARY_ACTION.fontSizeFp)
          .fontColor(readerAppColor('TOK_PRIMARY_TEXT', this.appThemeScheme));
      }
      .height(42)
      .layoutWeight(1)
      .backgroundColor(readerAppColor('app.SyncPage.GHOST_BG', this.appThemeScheme))
      .border({ width: TOK_BORDER_W, color: readerAppColor('app.SyncPage.GHOST_BORDER', this.appThemeScheme) })
      .borderRadius(8)
      .enabled(this.canMutate())
      .onClick((): void => this.onTestConnection(
        this.effectiveWebdavUrl().trim(), this.effectiveWebdavUser().trim(),
        this.webdavPass, this.effectiveWebdavPath().trim()));

      Stack({ alignContent: Alignment.Center }) {
        Text('保存配置')
          .fontFamily(TYPE_APP_COMPACT_PRIMARY_ACTION.fontFamily)
          .fontWeight(TYPE_APP_COMPACT_PRIMARY_ACTION.fontWeight)
          .fontSize(TYPE_APP_COMPACT_PRIMARY_ACTION.fontSizeFp)
          .fontColor(readerAppColor('TOK_ON_PRIMARY', this.appThemeScheme));
      }
      .height(42)
      .layoutWeight(1)
      .backgroundColor(readerAppColor('app.SyncPage.SOLID_BG', this.appThemeScheme))
      .border({ width: TOK_BORDER_W, color: readerAppColor('app.SyncPage.SOLID_BG', this.appThemeScheme) })
      .borderRadius(12)
      .enabled(this.canMutate())
      .onClick((): void => this.onSaveConfig(
        this.effectiveWebdavUrl().trim(), this.effectiveWebdavUser().trim(), this.webdavPass,
        this.backupPass, this.effectiveWebdavPath().trim()));
    }
    .width('100%');
  }
